import queue

import pytest


def accepted(cap: int, xs: list[int]) -> int:
    """Count the puts accepted by a bounded queue before it is full.

    Creates a queue of capacity `cap` and tries to put each element of `xs`
    in order without blocking. Stops at the first rejected put and returns
    the number of elements accepted. A non-positive `cap` accepts nothing.
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_more_items_than_capacity() -> None:
    assert accepted(3, [1, 2, 3, 4, 5]) == 3


def test_fewer_items_than_capacity() -> None:
    assert accepted(10, [1, 2, 3]) == 3


def test_exact_fit() -> None:
    assert accepted(3, [7, 8, 9]) == 3


def test_empty_input() -> None:
    assert accepted(5, []) == 0


def test_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_negative_capacity() -> None:
    assert accepted(-2, [1, 2]) == 0


def test_zero_capacity_empty_input() -> None:
    assert accepted(0, []) == 0


def test_capacity_one() -> None:
    assert accepted(1, [4, 5, 6]) == 1


def test_duplicates_are_counted() -> None:
    assert accepted(4, [1, 1, 1, 1, 1]) == 4


@pytest.mark.parametrize(
    ("cap", "xs", "expected"),
    [
        (2, [1, 2, 3], 2),
        (5, [1], 1),
        (0, [1], 0),
        (3, [], 0),
        (4, [0, -1, -2, -3, -4], 4),
    ],
)
def test_accepted_parametrized(cap: int, xs: list[int], expected: int) -> None:
    assert accepted(cap, xs) == expected


def test_input_not_modified() -> None:
    xs = [1, 2, 3, 4]
    accepted(2, xs)
    assert xs == [1, 2, 3, 4]

